<?php
/** Authorized archive reader. No creation, upload, review or historical-state mutation. */
require_once __DIR__.'/layout.php';require_once __DIR__.'/user_identities.php';
function legacy_communications_page(PDO $pdo,bool $management):void
{
    if($_SERVER['REQUEST_METHOD']!=='GET'){header('Allow: GET');http_response_code($_SERVER['REQUEST_METHOD']==='POST'?410:405);exit('Internal Board messaging is retired. Use Email for correspondence.');}
    header('Cache-Control: private, no-store');$uid=(int)$_SESSION['UserID'];$id=isset($_GET['id'])&&is_string($_GET['id'])&&ctype_digit($_GET['id'])?(int)$_GET['id']:0;$page=isset($_GET['page'])&&is_string($_GET['page'])&&ctype_digit($_GET['page'])?max(1,min(1000000,(int)$_GET['page'])):1;$rows=[];$detail=null;$error='';$total=0;$route=$management?'board_inbox.php':'board_messages.php';
    try{
        $where=$management?'1=1':'b.Sender_UserID=?';$params=$management?[]:[$uid];$s=$pdo->prepare('SELECT COUNT(*) FROM Board_Communications b WHERE '.$where);$s->execute($params);$total=(int)$s->fetchColumn();$page=min($page,max(1,(int)ceil($total/50)));
        $projection='SELECT b.CommunicationID,b.Subject,b.Message_Body,b.File_Path,b.Review_Status,b.Created_At,u.FullName SenderName FROM Board_Communications b JOIN '.user_identity_table($pdo).' u ON u.UserID=b.Sender_UserID';
        $s=$pdo->prepare($projection.' WHERE '.$where.' ORDER BY b.Created_At DESC,b.CommunicationID DESC LIMIT 50 OFFSET '.(($page-1)*50));$s->execute($params);$rows=$s->fetchAll();
        if($id){$s=$pdo->prepare($projection.' WHERE '.$where.' AND b.CommunicationID=?');$s->execute(array_merge($params,[$id]));$detail=$s->fetch()?:null;if(!$detail){http_response_code(404);$error='That historical message is unavailable for your account.';}}
    }catch(Throwable $e){http_response_code(503);$error='Historical communications could not be loaded. Please try again.';}
    layout_begin('Legacy Communications Archive','external_email');ui_page_heading('Legacy Communications Archive','Read Only · Internal Board messaging is retired.','<a class="ui-button" href="external_email.php">Open Email</a>');
    if($error!=='')echo '<p role="alert">'.ui_escape($error).'</p>';
    ?><div class="ui-archive"><section class="ui-card"><h2>Historical Messages</h2><?php if(!$rows&&$error===''): ?><p>No historical messages are available.</p><?php endif; ?><?php foreach($rows as $row): ?><a class="ui-archive-row" href="<?= $route ?>?page=<?= $page ?>&amp;id=<?= (int)$row['CommunicationID'] ?>"><strong><?= ui_escape($row['Subject']) ?></strong><span><?= ui_escape($row['SenderName']) ?> · <?= ui_escape($row['Created_At']) ?></span></a><?php endforeach; ?><div class="ui-actions"><?php if($page>1): ?><a class="ui-button" href="<?= $route ?>?page=<?= $page-1 ?>">Previous</a><?php endif; ?><span>Page <?= $page ?> of <?= max(1,(int)ceil($total/50)) ?></span><?php if($page*50<$total): ?><a class="ui-button" href="<?= $route ?>?page=<?= $page+1 ?>">Next</a><?php endif; ?></div></section><section class="ui-card"><?php if($detail): ?><h2><?= ui_escape($detail['Subject']) ?></h2><p class="ui-quiet"><?= ui_escape($detail['SenderName']) ?> · <?= ui_escape($detail['Created_At']) ?></p><p class="ui-quiet">Historical status: <?= ui_escape($detail['Review_Status']) ?>. No further review action is available.</p><div class="ui-message-body"><?= nl2br(ui_escape($detail['Message_Body'])) ?></div><?php if($detail['File_Path']): ?><a class="ui-button" href="board_attachment.php?id=<?= (int)$detail['CommunicationID'] ?>">Open Historical Attachment</a><?php endif; ?><?php else: ?><p>Select a historical message to read it.</p><?php endif; ?></section></div><?php layout_end();
}
